if doc.custom_retail_packing_detail:

    for row in doc.custom_retail_packing_detail:

        selling_rate = row.selling_rate or 0

        if selling_rate > 0:

            price_name = frappe.db.get_value(
                "Item Price",
                {
                    "item_code": doc.item_code,
                    "uom": row.uom,
                    "price_list": "Standard Selling"
                }
            )

            if price_name:

                frappe.db.set_value(
                    "Item Price",
                    price_name,
                    "price_list_rate",
                    selling_rate
                )

            else:

                new_price = frappe.get_doc({
                    "doctype": "Item Price",
                    "item_code": doc.item_code,
                    "price_list": "Standard Selling",
                    "price_list_rate": selling_rate,
                    "uom": row.uom
                })

                new_price.insert(ignore_permissions=True)

purchase_rate = doc.last_purchase_rate or 0

if purchase_rate:
    price_list = "Standard Buying"
    price_name = frappe.db.get_value("Item Price", {
        "item_code": doc.name,
        "price_list": price_list,
        "uom": doc.stock_uom
    })

    if price_name:
        frappe.db.set_value("Item Price", price_name, "price_list_rate", purchase_rate)
    else:
        frappe.get_doc({
            "doctype": "Item Price",
            "item_code": doc.name,
            "price_list": price_list,
            "price_list_rate": purchase_rate,
            "uom": doc.stock_uom
        }).insert(ignore_permissions=True)

# Loop through every row in your Unified Packing table
if doc.custom_retail_packing_detail:
    for row in doc.custom_retail_packing_detail:
        
        # 1. HANDLE SELLING PRICES
        if row.selling_rate > 0:
            # Look for existing price for this specific Item + UOM + Price List
            sell_price_name = frappe.db.get_value("Item Price", {
                "item_code": doc.name,
                "uom": row.uom,
                "price_list": "Standard Selling"
            })

            if sell_price_name:
                frappe.db.set_value("Item Price", sell_price_name, "price_list_rate", row.selling_rate)
            else:
                frappe.get_doc({
                    "doctype": "Item Price",
                    "item_code": doc.name,
                    "price_list": "Standard Selling",
                    "price_list_rate": row.selling_rate,
                    "uom": row.uom
                }).insert(ignore_permissions=True)

        # 2. HANDLE PURCHASE PRICES
        if row.purchase_rate > 0:
            # Using 'Standard Buying' as you confirmed earlier
            buy_price_name = frappe.db.get_value("Item Price", {
                "item_code": doc.name,
                "uom": row.uom,
                "price_list": "Standard Buying"
            })

            if buy_price_name:
                frappe.db.set_value("Item Price", buy_price_name, "price_list_rate", row.purchase_rate)
            else:
                frappe.get_doc({
                    "doctype": "Item Price",
                    "item_code": doc.name,
                    "price_list": "Standard Buying",
                    "price_list_rate": row.purchase_rate,
                    "uom": row.uom
                }).insert(ignore_permissions=True)

# -----------------------------
# Sync UOM Table
# -----------------------------

default_uom = doc.stock_uom or "Nos"

doc.set("uoms", [])

# base uom mandatory
doc.append("uoms", {
    "uom": default_uom,
    "conversion_factor": 1
})

seen_uoms = {default_uom}

for row in (doc.custom_retail_packing_detail or []):

    if row.uom and row.uom not in seen_uoms:

        doc.append("uoms", {
            "uom": row.uom,
            "conversion_factor": row.conversion_factor or 1
        })
        seen_uoms.add(row.uom)

# -----------------------------
# Sync Barcode Table
# -----------------------------

doc.set("barcodes", [])
seen_barcodes = set()

# quick/default barcode from the Item form
if doc.custom_barcode:
    barcode = doc.custom_barcode.strip()
    if barcode:
        doc.append("barcodes", {
            "barcode": barcode,
            "uom": default_uom
        })
        seen_barcodes.add(barcode)

# advanced multi-UOM barcodes from Retail Packing Detail
for row in (doc.custom_retail_packing_detail or []):

    if row.barcode:
        barcode = row.barcode.strip()
        if barcode and barcode not in seen_barcodes:

            doc.append("barcodes", {
                "barcode": barcode,
                "uom": row.uom or default_uom
            })
            seen_barcodes.add(barcode)
